"""Exact Tech/Twinborn/Overload data exported from the supplied sIO runtime.

The JSON is zlib-compressed only to keep the generated source compact.
"""
from __future__ import annotations
import base64
import json
import zlib

_COMPRESSED = ""
SIO_TECH_DATA = json.loads(zlib.decompress(base64.b64decode(_COMPRESSED)).decode("utf-8"))
